int __fastcall AETHER_validate_certificate(AETHER_cert_ctx *ctx, const char *cert_pem, size_t cert_len)
{
  int status;
  uint8_t *decoded;
  size_t decoded_len;

  // Decode the PEM-encoded certificate into raw DER bytes
  decoded = base64_decode(cert_pem, cert_len, &decoded_len);
  if (!decoded)
    return -1;  // Invalid PEM encoding

  // Parse the X.509 certificate structure
  status = x509_parse(decoded, decoded_len, &ctx->parsed);
  if (status != 0) {
    free(decoded);
    return status;  // X.509 parsing failed
  }

  // Verify certificate chain against trusted anchors
  status = chain_verify(&ctx->parsed, &ctx->anchor_pool, ctx->anchor_count);
  if (status != 0) {
    ctx->last_error = CERT_CHAIN_FAILED;
  }

  // Check certificate expiration
  if (!check_validity_period(&ctx->parsed)) {
    ctx->last_error = CERT_EXPIRED;
    free(decoded);
    return -2;
  }

  free(decoded);
  return status;
}

